// 1) Берём сырой текст от агента
const raw =
  $json?.output ??
  $json?.text ??
  $json?.response ??
  $json?.message ??
  $json?.data?.text ??
  $json?.data ??
  $json;

const rawStr = typeof raw === "string" ? raw : JSON.stringify(raw);

// 2) Пытаемся найти 1+ JSON объектов в строке и взять последний валидный
let agent = null;

// Разобьём по строкам и попробуем распарсить каждую строку как JSON
const lines = rawStr
  .split(/\n+/)
  .map(s => s.trim())
  .filter(s => s.startsWith("{") && s.endsWith("}"));

for (const s of lines) {
  try {
    const obj = JSON.parse(s);
    if (obj && obj.type && obj.reply) agent = obj; // берём последний подходящий
  } catch (e) {}
}

// Если не нашли по строкам — пробуем вытащить JSON-объекты regex-ом
if (!agent) {
  const matches = rawStr.match(/\{[\s\S]*?\}/g) || [];
  for (const s of matches) {
    try {
      const obj = JSON.parse(s);
      if (obj && obj.type && obj.reply) agent = obj;
    } catch (e) {}
  }
}

// Если всё равно не получилось — падаем с понятной ошибкой
if (!agent) {
  throw new Error("Не смогла вытащить JSON от агента. rawStr=" + rawStr);
}

// 3) Достаём service_tag (если агент его вернул)
let service_tag = agent.service_tag;

if (!service_tag) {
  // запасной вариант: если агент добавил строку SERVICE_TAG: manicure
  const m = rawStr.match(/SERVICE_TAG:\s*(massage|manicure|brows_lashes|unknown)/i);
  if (m) service_tag = m[1].toLowerCase();
}

if (!service_tag) service_tag = "unknown";

// 4) Возвращаем в поток удобные поля
return [{ ...$json, agent, rawStr, service_tag }];

