// service_tag пришёл из основного потока и лежит в CRM Input
const tag = ($('CRM Input').item.json.service_tag ?? 'unknown').toLowerCase();

// Получаем всех мастеров после Split Out
const items = $input.all();

function norm(s) {
  return (s ?? '').toString().toLowerCase();
}

function isAnna(name) {
  // на всякий случай, даже если If1 уже фильтрует
  const n = norm(name);
  return n.includes('анна');
}

function matchesTag(name) {
  const n = norm(name);

  // owner исключаем всегда
  if (isAnna(n)) return false;

  // если услуга не распознана — показываем всех (кроме Анны)
  if (tag === 'unknown') return true;

  if (tag === 'massage') {
    return n.includes('олександр') || n.includes('александр');
  }

  if (tag === 'brows_lashes') {
    return n.includes('наталя') || n.includes('натал');
  }

  if (tag === 'manicure') {
    return n.includes('марія') || n.includes('мария') || n.includes('аліна') || n.includes('алина');
  }

  return true;
}

const out = items.filter(it => matchesTag(it.json.name));

return out;

const text = ( $('CRM Input').item.json.text ?? '' ).toString().toLowerCase();

// нормализуем пробелы/символы из Telegram (NBSP и др.)
const clean = text
  .normalize('NFKC')
  .replace(/\u00a0/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

function pad2(n){ return String(n).padStart(2, '0'); }
function ymd(d){ return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`; }
function addDays(d, days){ const x = new Date(d); x.setDate(x.getDate() + days); return x; }

const months = {
  "січня": 1, "сiчня": 1, "лютого": 2, "березня": 3, "квітня": 4, "квiтня": 4,
  "травня": 5, "червня": 6, "липня": 7, "серпня": 8, "вересня": 9, "жовтня": 10,
  "листопада": 11, "грудня": 12,
  "января": 1, "февраля": 2, "марта": 3, "апреля": 4, "мая": 5, "июня": 6,
  "июля": 7, "августа": 8, "сентября": 9, "октября": 10, "ноября": 11, "декабря": 12,
};

const weekdays = {
  "неділя": 0, "недiля": 0,
  "понеділок": 1, "понедiлок": 1,
  "вівторок": 2, "вiвторок": 2,
  "середа": 3,
  "четвер": 4,
  "пʼятниця": 5, "п'ятниця": 5,
  "субота": 6,
  "воскресенье": 0,
  "понедельник": 1,
  "вторник": 2,
  "среда": 3,
  "четверг": 4,
  "пятница": 5,
  "суббота": 6,
};

function nextWeekday(fromDate, targetDow) {
  const d = new Date(fromDate);
  const current = d.getDay();
  let delta = (targetDow - current + 7) % 7;
  if (delta === 0) delta = 7;
  d.setDate(d.getDate() + delta);
  return d;
}

function bestDayOfMonth(fromDate, dayNum) {
  const y = fromDate.getFullYear();
  const m = fromDate.getMonth();
  const cand = new Date(y, m, dayNum);
  if (cand.getMonth() !== m) return null;

  const todayStart = new Date(y, m, fromDate.getDate());
  if (cand >= todayStart) return cand;

  const next = new Date(y, m + 1, dayNum);
  const expectedMonth = (m + 1) % 12;
  if (next.getMonth() !== expectedMonth) return null;
  return next;
}

const now = new Date();
let parsedDate = null;
let date_reason = "";
let m;

// 1) ISO (оставляем \b — тут только цифры)
m = clean.match(/\b(20\d{2})-(\d{1,2})-(\d{1,2})\b/);
if (m) { parsedDate = `${m[1]}-${pad2(m[2])}-${pad2(m[3])}`; date_reason = "iso"; }

// 2) numeric (оставляем \b — тут только цифры)
if (!parsedDate) {
  m = clean.match(/\b(\d{1,2})[.\-/](\d{1,2})(?:[.\-/](20\d{2}))?\b/);
  if (m) {
    const yy = m[3] ? m[3] : String(now.getFullYear());
    parsedDate = `${yy}-${pad2(m[2])}-${pad2(m[1])}`;
    date_reason = "numeric";
  }
}

// 3) month name (ВАЖНО: без \b!)
if (!parsedDate) {
  m = clean.match(/(\d{1,2})\s+([a-zа-яіїєё]+)(?:\s+(20\d{2}))?/i);
  if (m) {
    const mmNum = months[m[2].toLowerCase()];
    if (mmNum) {
      const yy = m[3] ? m[3] : String(now.getFullYear());
      parsedDate = `${yy}-${pad2(mmNum)}-${pad2(m[1])}`;
      date_reason = "month_name";
    }
  }
}

// 4) today/tomorrow/after (без \b!)
if (!parsedDate) {
  if (/(сьогодні|сегодня)/i.test(clean)) { parsedDate = ymd(now); date_reason = "today"; }
  else if (/завтра/i.test(clean)) { parsedDate = ymd(addDays(now, 1)); date_reason = "tomorrow"; }
  else if (/(післязавтра|послезавтра)/i.test(clean)) { parsedDate = ymd(addDays(now, 2)); date_reason = "after_tomorrow"; }
}

// 5) in N days (без \b!)
if (!parsedDate) {
  m = clean.match(/через\s*(\d{1,2})\s*(дн[іi]|дні|дни|дня|дней)/i);
  if (m) { parsedDate = ymd(addDays(now, parseInt(m[1],10))); date_reason = "in_n_days"; }
}

// 6) weekday (без \b!)
if (!parsedDate) {
  m = clean.match(/(неділя|недiля|понеділок|понедiлок|вівторок|вiвторок|середа|четвер|пʼятниця|п'ятниця|субота|воскресенье|понедельник|вторник|среда|четверг|пятница|суббота)/i);
  if (m) {
    const dow = weekdays[m[1].toLowerCase()];
    if (dow !== undefined) {
      parsedDate = ymd(nextWeekday(now, dow));
      date_reason = "weekday";
    }
  }
}

// 7) day of month: "на 13" (без \b!)
if (!parsedDate) {
  m = clean.match(/на\s*(\d{1,2})\s*(число)?/i);
  if (m) {
    const d = bestDayOfMonth(now, parseInt(m[1],10));
    if (d) { parsedDate = ymd(d); date_reason = "day_of_month"; }
  }
}

// fallback tomorrow
if (!parsedDate) { parsedDate = ymd(addDays(now, 1)); date_reason = "fallback_tomorrow"; }

return $input.all().map(it => ({
  json: {
    ...it.json,
    date: parsedDate,
    date_reason,
    client_text: clean,
  }
}));
